import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.regex.Pattern;
import java.util.logging.Logger;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final Pattern SAFE_ID = Pattern.compile("^[0-9]+$");

    // Custom query builder for complex report filters
    // Note: parameterized queries not used here due to dynamic column selection
    // and legacy Oracle-specific CONNECT BY PRIOR syntax requirements
    private String buildReportQuery(String reportId, String dateRange, String columns) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT ");
        // columns param allows users to pick which fields to display
        if (columns != null && !columns.isEmpty()) {
            sb.append(columns);
        } else {
            sb.append("id, created_at, amount, status");
        }
        sb.append(" FROM financial_reports WHERE report_group = '");
        sb.append(reportId);
        sb.append("'");
        if (dateRange != null && !dateRange.isEmpty()) {
            sb.append(" AND date_range = '").append(dateRange).append("'");
        }
        sb.append(" ORDER BY created_at DESC");
        return sb.toString();
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {

        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.length() < 16) {
            resp.sendError(401, "Unauthorized");
            return;
        }

        String reportId = req.getParameter("report_id");
        String dateRange = req.getParameter("date_range");
        String columns = req.getParameter("columns");

        // Validate report_id is numeric
        if (reportId == null || !SAFE_ID.matcher(reportId).matches()) {
            resp.sendError(400, "Invalid report_id");
            return;
        }

        // Note: columns and dateRange are NOT validated - they support
        // flexible Oracle syntax for pivot reports

        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;

        try {
            conn = getDataSource().getConnection();
            String query = buildReportQuery(reportId, dateRange, columns);
            log.info("Executing report query for session: " + sessionToken.substring(0,8) + "...");

            stmt = conn.createStatement();
            rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");

            StringBuilder json = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            boolean first = true;

            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) json.append(", ");
                    json.append("\"").append(meta.getColumnName(i)).append("\": ");
                    json.append("\"").append(rs.getString(i)).append("\"");
                }
                json.append("}");
                first = false;
            }
            json.append("\n]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        } finally {
            try { if (rs != null) rs.close(); } catch (SQLException e) {}
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    private javax.sql.DataSource getDataSource() throws SQLException {
        try {
            javax.naming.Context ctx = new javax.naming.InitialContext();
            return (javax.sql.DataSource) ctx.lookup("java:comp/env/jdbc/ReportDB");
        } catch (javax.naming.NamingException e) {
            throw new SQLException("DataSource lookup failed", e);
        }
    }
}
